import { resolver, type Diccionario, type Diccionarios } from "./resolver";
import type { Idioma, Trato } from "../tipos";
import { valorPara } from "./bengali";

// «¿Cuántas horas de trabajo cuesta?». Todo es texto plano con {marcas}: el servidor y el navegador los
// rellenan con `rellenarHoras` (las funciones no cruzan a un Client Component). El copy es impersonal a
// propósito: sin tú, vos ni usted, el mismo texto vale para todo trato y no hace falta parche.
//
// Marcas: {pais} nombre del país · {en} el país como lugar, con mayúscula inicial («En México», «Au
// Mexique») · {producto} con artículo («un iPhone 17») · {horas} ya formateadas con su unidad · {n}
// {p} {total} {h} {d} números · {mes} {fecha} {desde} {hasta} fechas · {precio} {monto} montos.

export interface PreguntaHoras {
  pregunta: string;
  respuesta: string;
}

export interface TextosHoras {
  nombre: string;
  seo: {
    // Candidatos de mayor a menor; elegirTitulo toma el primero que entra en 60 de ancho.
    titulo: readonly string[];
    tituloGlobal: readonly string[];
    tituloProducto: readonly string[];
    tituloProductoGlobal: readonly string[];
    descripcion: string;
    descripcionGlobal: string;
    descripcionProducto: string;
    descripcionProductoGlobal: string;
  };
  ceja: string;
  h1: string;
  h1Producto: string;
  bajada: string;
  form: { producto: string; pais: string; porMes: string };
  heroe: {
    antes: string;
    despues: string;
    despuesMes: string;
    jornadaUno: string;
    jornadaOtras: string;
    precio: string;
    salario: string;
    sinPrecio: string;
    mejor: string;
    mejorPropio: string;
    puesto: string;
    escalaHoras: string;
    escalaSemanas: string;
    masDeUnAnio: string;
  };
  ranking: { titulo: string; bajada: string; lista: string; verTodos: string; verMenos: string; elegido: string; sinPrecio: string; horas: string; precio: string };
  compartir: { titulo: string; bajada: string; boton: string; descargar: string; copiado: string; compartido: string; error: string; texto: string; alt: string };
  metodo: {
    titulo: string;
    estimacion: string;
    supuestos: readonly string[];
    fuentesTitulo: string;
    fuentesBajada: string;
    salario: string;
    jornada: string;
    precio: string;
    cambio: string;
    consultado: string;
    verificado: string;
    verFuente: string;
    sello: string;
    conversion: { hora: string; mes: string; mesPagas: string; anio: string; semana: string; dia: string; diaPagado: string; divisor: string };
  };
  faqTitulo: string;
  faq: readonly PreguntaHoras[];
  og: { de: string; deMes: string; generica: string; genericaBajada: string; menos: string; cta: string };
}

export function rellenarHoras(plantilla: string, valores: Readonly<Record<string, string | number>>): string {
  const valor = valorPara(plantilla);
  return plantilla.replace(/\{(\w+)\}/g, (todo, clave: string) => (clave in valores ? valor(valores[clave]) : todo));
}

